import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Redacted from "effect/Redacted";
import * as FetchHttpClient from "effect/unstable/http/FetchHttpClient";
import { Credentials } from "@distilled.cloud/kubernetes/Credentials";

function distilledLayer(apiKey: string, runtimeConfig?: import("./runtime.ts").RuntimeConfig) {
	return Layer.mergeAll(
		FetchHttpClient.layer,
		Layer.succeed(Credentials, { token: Redacted.make(apiKey), apiBaseUrl: runtimeConfig?.baseUrl || "https://kubernetes.default.svc" }),
	);
}

async function runDistilled<Input, Output>(
	operation: (input: Input) => Effect.Effect<Output, unknown, unknown>,
	input: Input,
	apiKey: string | undefined,
	options?: CallOptions,
	runtimeConfig?: import("./runtime.ts").RuntimeConfig,
): Promise<Output> {
	const effectiveApiKey = options?.auth?.apiKey ?? apiKey;
	if (!effectiveApiKey) throw new Error("set the capability API key secret or pass options.auth.apiKey");
	const effect = operation(input).pipe(Effect.provide(distilledLayer(effectiveApiKey, runtimeConfig))) as Effect.Effect<Output, unknown, never>;
	return Effect.runPromise(effect);
}

